import React, { useState } from "react";
import api from "../services/api";

export default function ShareCapital() {
  const [id, setId] = useState("");
  const [data, setData] = useState(null);
  const [err, setErr] = useState("");

  const load = async (e) => {
    e.preventDefault();

    if (!id.trim()) {
      setErr("Please enter a Member ID.");
      setData(null);
      return;
    }

    try {
      setErr("");
      setData(null);

      // Your backend provides share capital through the passbook API
      const response = await api.get(`/members/${id}/passbook`);

      setData(response.data);
    } catch (e) {
      console.error("Share capital error:", e);

      setData(null);

      setErr(
          e.response?.data?.message ||
          "Unable to load share capital."
      );
    }
  };

  return (
      <>
        {/* Page Header */}
        <div className="page-head">
          <div>
          <span className="eyebrow">
            COOPERATIVE EQUITY
          </span>

            <h2>
              Share Capital
            </h2>

            <p>
              Check a member's share capital balance.
            </p>
          </div>
        </div>

        {/* Search Form */}
        <form
            className="inline-form"
            onSubmit={load}
        >
          <input
              type="text"
              value={id}
              onChange={(e) => setId(e.target.value)}
              placeholder="Enter Member ID (e.g. 3)"
          />

          <button
              type="submit"
              className="primary"
          >
            Check balance
          </button>
        </form>

        {/* Error Message */}
        {err && (
            <div className="alert">
              {err}
            </div>
        )}

        {/* Share Capital Result */}
        {data && (
            <div className="share-card">

              {/* Member Information */}
              <div className="share-info">

                <div className="rupee-icon">
                  ₹
                </div>

                <div>
              <span className="member-id">
                {data.member?.memberId || "-"}
              </span>

                  <h3>
                    {data.member?.name || "-"}
                  </h3>

                  <p>
                    Current share capital
                  </p>
                </div>

              </div>

              {/* Share Capital Amount */}
              <div className="share-amount">
                ₹{data.shareCapital || 0}
              </div>

            </div>
        )}
      </>
  );
}
